INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20801, 'គណនា \(dy\) នៃ \(y=x^2\) ត្រង់ \(x=3\) និង \(dx=0{,}1\)។', NULL, '["\\(6\\)", "\\(0{,}6\\)", "\\(0{,}3\\)", "\\(0{,}61\\)"]', 1, NULL, 1, 'mcq', '\(dy=f''(x)\,dx=2x\,dx=2\cdot3\cdot0{,}1=0{,}6\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20802, 'ប្រាក់ចំណាយសរុប \(C(x)=500+3x\) (ពាន់រៀល) ។ ប្រាក់ចំណាយម៉ាជីណាល \(C''(x)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(3x\\)", "\\(500\\)", "\\(3\\)", "\\(503\\)"]', 2, NULL, 1, 'mcq', '\(C''(x)=3\) ពាន់រៀល (ថេរ) ជាអត្រាបម្រែបម្រួលប្រាក់ចំណាយ។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20803, 'ទំនាក់ទំនងរវាងប្រាក់ចំណេញ \(P\) ប្រាក់ចំណូល \(R\) និងប្រាក់ចំណាយ \(C\) គឺ ៖', NULL, '["\\(P(x)=C(x)-R(x)\\)", "\\(P(x)=\\dfrac{R(x)}{C(x)}\\)", "\\(P(x)=R(x)+C(x)\\)", "\\(P(x)=R(x)-C(x)\\)"]', 3, NULL, 1, 'mcq', 'ប្រាក់ចំណេញសរុប \(=\) ប្រាក់ចំណូលសរុប \(-\) ប្រាក់ចំណាយសរុប។', 'ប្រាក់ចំណេញម៉ាជីណាល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20804, 'ប្រាក់ចំណាយ \(C(x)=0{,}1x^2+5x+200\) ។ ប្រាក់ចំណាយមធ្យម \(\overline C(10)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(260\\)", "\\(20\\)", "\\(26\\)", "\\(6\\)"]', 2, NULL, 1, 'mcq', '\(C(10)=10+50+200=260\) ដូច្នេះ \(\overline C(10)=\dfrac{260}{10}=26\)។', 'ប្រាក់ចំណាយមធ្យម', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20805, 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ \(\sqrt{26}\)។', NULL, '["\\(5{,}01\\)", "\\(5{,}1\\)", "\\(5{,}05\\)", "\\(5{,}2\\)"]', 1, NULL, 1, 'mcq', 'តាង \(f(x)=\sqrt x\), \(x=25\), \(dx=1\) ៖ \(dy=\dfrac1{2\sqrt{25}}=0{,}1\) ដូច្នេះ \(\sqrt{26}\approx5+0{,}1=5{,}1\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20806, 'តម្លៃលក់ \(p(x)=50-x\) ពាន់រៀល/គ្រឿង ។ ប្រាក់ចំណូលសរុប \(R(x)\) គឺ ៖', NULL, '["\\(50-2x\\)", "\\(50x-x^2\\)", "\\(50-x\\)", "\\(50x+x^2\\)"]', 1, NULL, 1, 'mcq', '\(R(x)=p(x)\cdot x=(50-x)x=50x-x^2\)។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20807, 'ឌីផេរ៉ង់ស្យែល \(dy\) នៃអនុគមន៍ \(y=f(x)\) កំណត់ដោយ ៖', NULL, '["\\(dy=f''(x)\\,dx\\)", "\\(dy=\\dfrac{dx}{f''(x)}\\)", "\\(dy=f''''(x)\\,dx\\)", "\\(dy=f(x)\\,dx\\)"]', 0, NULL, 1, 'mcq', 'និយមន័យ ៖ \(dy=f''(x)\,dx\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20808, 'ប្រាក់ចំណាយម៉ាជីណាល \(C''(x)\) មានតម្លៃប្រហែលនឹងអ្វី ?', NULL, '["\\(C(x+1)-C(x)\\) (ប្រាក់ចំណាយគ្រឿងបន្ទាប់)", "\\(C(x)+C(x+1)\\)", "\\(C(x)-C(x-1)\\cdot x\\)", "\\(C(x)/x\\)"]', 0, NULL, 1, 'mcq', '\(C''(x)\approx C(x+1)-C(x)\)។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20809, 'រូបមន្តប៉ាន់ស្មានតម្លៃដោយប្រើឌីផេរ៉ង់ស្យែលគឺ ៖', NULL, '["\\(f(x+\\Delta x)\\approx f(x)+f''(x)\\,\\Delta x\\)", "\\(f(x+\\Delta x)\\approx f''(x)\\,\\Delta x\\)", "\\(f(x+\\Delta x)\\approx f(x)\\cdot\\Delta x\\)", "\\(f(x+\\Delta x)\\approx f(x)-f''(x)\\)"]', 0, NULL, 1, 'mcq', '\(f(x+\Delta x)=f(x)+\Delta y\approx f(x)+dy\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20810, 'ប្រាក់ចំណូលសរុប \(R(x)=100x-0{,}5x^2\) ។ ប្រាក់ចំណូលម៉ាជីណាល \(R''(40)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(100\\)", "\\(40\\)", "\\(80\\)", "\\(60\\)"]', 3, NULL, 1, 'mcq', '\(R''(x)=100-x\) ដូច្នេះ \(R''(40)=60\) ពាន់រៀល។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'easy', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20811, 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ \(\sqrt[3]{28}\)។', NULL, '["\\(3{,}33\\)", "\\(3{,}037\\)", "\\(3{,}003\\)", "\\(3{,}1\\)"]', 1, NULL, 2, 'mcq', '\(f(x)=\sqrt[3]x\), \(f''(27)=\dfrac1{3\cdot9}=\dfrac1{27}\) ដូច្នេះ \(\sqrt[3]{28}\approx3+\dfrac1{27}\approx3{,}037\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20812, 'បើ \(1\le f''(x)\le3\) ចំពោះគ្រប់ \(x\in[0,2]\) តើ \(f(2)-f(0)\) ស្ថិតក្នុងចន្លោះណា ?', NULL, '["\\([3,\\ 9]\\)", "\\([1,\\ 3]\\)", "\\([2,\\ 6]\\)", "\\([0,\\ 2]\\)"]', 2, NULL, 2, 'mcq', '\(m(b-a)\le f(b)-f(a)\le M(b-a)\) ជាមួយ \(m=1,\ M=3,\ b-a=2\) ៖ \(2\le f(2)-f(0)\le6\)។', 'វិសមភាពកំណើនមានកំណត់', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20813, 'ប្រាក់ចំណាយ \(C(x)=0{,}1x^2+4x+100\) ។ ប្រាក់ចំណាយម៉ាជីណាល \(C''(20)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(12\\)", "\\(4\\)", "\\(8\\)", "\\(0{,}2\\)"]', 2, NULL, 2, 'mcq', '\(C''(x)=0{,}2x+4\) ដូច្នេះ \(C''(20)=8\)។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20814, 'ប្រាក់ចំណេញ \(P(x)=-0{,}5x^2+40x-200\) ។ ប្រាក់ចំណេញម៉ាជីណាល \(P''(30)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(25\\)", "\\(-10\\)", "\\(40\\)", "\\(10\\)"]', 3, NULL, 2, 'mcq', '\(P''(x)=-x+40\) ដូច្នេះ \(P''(30)=10\)។', 'ប្រាក់ចំណេញម៉ាជីណាល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20815, 'ប្រាក់ចំណាយ \(C(x)=0{,}05x^2+3x+400\) ។ ប្រាក់ចំណាយមធ្យមម៉ាជីណាល \(\overline C''(20)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(0{,}95\\)", "\\(-1\\)", "\\(0{,}05\\)", "\\(-0{,}95\\)"]', 3, NULL, 2, 'mcq', '\(\overline C(x)=0{,}05x+3+\dfrac{400}x\) ; \(\overline C''(x)=0{,}05-\dfrac{400}{x^2}\) ដូច្នេះ \(\overline C''(20)=0{,}05-1=-0{,}95\)។', 'ប្រាក់ចំណាយមធ្យម', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20816, 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ \(\sin29^\circ\)។', NULL, '["\\(\\dfrac{\\sqrt3}2-\\dfrac{\\pi}{360}\\approx0{,}857\\)", "\\(\\dfrac12+\\dfrac{\\pi\\sqrt3}{360}\\approx0{,}515\\)", "\\(\\dfrac12-\\dfrac{\\pi}{180}\\approx0{,}483\\)", "\\(\\dfrac12-\\dfrac{\\pi\\sqrt3}{360}\\approx0{,}485\\)"]', 3, NULL, 2, 'mcq', '\(x=30^\circ=\dfrac\pi6\), \(dx=-1^\circ=-\dfrac\pi{180}\) ៖ \(dy=\cos\dfrac\pi6\cdot\left(-\dfrac\pi{180}\right)=-\dfrac{\pi\sqrt3}{360}\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20817, 'ចំពោះគ្រប់ \(x,y\in\mathbb{R}\) វិសមភាពមួយណាត្រឹមត្រូវ ?', NULL, '["\\(|\\sin x-\\sin y|\\le|x-y|\\)", "\\(|\\sin x-\\sin y|\\ge|x-y|\\)", "\\(|\\sin x-\\sin y|\\le\\dfrac12|x-y|\\)", "\\(|\\sin x-\\sin y|\\le2|x-y|\\cdot|x|\\)"]', 0, NULL, 2, 'mcq', '\(|(\sin t)''|=|\cos t|\le1\) ដូច្នេះ \(M=1\) ។ (វិសមភាព \(\le2|x-y|\) ក៏ពិតដែរ ប៉ុន្តែឆ្លើយនេះជាផ្លូវតូចបំផុតដែលមាន \(M=1\))។', 'វិសមភាពកំណើនមានកំណត់', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20818, 'ប្រាក់ចំណូល \(R(x)=60x-0{,}2x^2\) ។ ប្រាក់ចំណូលម៉ាជីណាល \(R''(30)\) ស្មើប៉ុន្មាន ?', NULL, '["\\(36\\)", "\\(48\\)", "\\(54\\)", "\\(60\\)"]', 1, NULL, 2, 'mcq', '\(R''(x)=60-0{,}4x\) ដូច្នេះ \(R''(30)=48\)។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20819, 'ប្រាក់ចំណេញ \(P(x)=-0{,}5x^2+40x-200\) ។ ចំណេញអតិបរមាកើតនៅកម្រិតផលិតកម្មណា ?', NULL, '["\\(x=40\\)", "\\(x=80\\)", "\\(x=20\\)", "\\(x=30\\)"]', 0, NULL, 2, 'mcq', '\(P''(x)=-x+40=0\) ឱ្យ \(x=40\) (ប្រាក់ចំណេញម៉ាជីណាលស្មើសូន្យ) ហើយ \(P(40)=600\)។', 'ប្រាក់ចំណេញម៉ាជីណាល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20820, 'ប្រាក់ចំណាយ \(C(x)=0{,}02x^2+10x+800\) ។ តើផលិត \(x\) ប៉ុន្មានគ្រឿងដើម្បីឱ្យប្រាក់ចំណាយមធ្យមតូចបំផុត ?', NULL, '["\\(x=400\\)", "\\(x=100\\)", "\\(x=200\\)", "\\(x=40\\)"]', 2, NULL, 2, 'mcq', '\(\overline C=0{,}02x+10+\dfrac{800}x\) ; \(\overline C''=0{,}02-\dfrac{800}{x^2}=0\) ឱ្យ \(x^2=40\,000\) គឺ \(x=200\)។', 'ប្រាក់ចំណាយមធ្យម', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20821, 'គូបមួយមានជ្រុង \(10\ \text{cm}\) វាស់លម្អៀង \(\pm0{,}1\ \text{cm}\) ។ តើមាឌលម្អៀងប្រហែលប៉ុន្មាន ?', NULL, '["\\(\\pm3\\ \\text{cm}^3\\)", "\\(\\pm30\\ \\text{cm}^3\\)", "\\(\\pm10\\ \\text{cm}^3\\)", "\\(\\pm300\\ \\text{cm}^3\\)"]', 1, NULL, 2, 'mcq', '\(V=x^3\) ; \(dV=3x^2\,dx=3\cdot100\cdot0{,}1=30\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20822, 'ស្វ៊ែរមួយមានកាំ \(5\ \text{cm}\) វាស់លម្អៀង \(\pm0{,}05\ \text{cm}\) ។ តើផ្ទៃក្រឡា \(S=4\pi r^2\) លម្អៀងប្រហែលប៉ុន្មាន ?', NULL, '["\\(\\pm0{,}4\\pi\\ \\text{cm}^2\\)", "\\(\\pm4\\pi\\ \\text{cm}^2\\)", "\\(\\pm2\\pi\\ \\text{cm}^2\\)", "\\(\\pm\\pi\\ \\text{cm}^2\\)"]', 2, NULL, 2, 'mcq', '\(dS=8\pi r\,dr=8\pi\cdot5\cdot0{,}05=2\pi\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20823, 'ការប៉ាន់ស្មាន \(\sqrt{15}\approx3{,}875\) តាមឌីផេរ៉ង់ស្យែលធំជាង ឬតូចជាងតម្លៃពិត ?', NULL, '["មិនអាចកំណត់បាន", "ស្មើតម្លៃពិត", "តូចជាងតម្លៃពិត ព្រោះ \\(dx<0\\)", "ធំជាងតម្លៃពិត ព្រោះក្រាបនៃ \\(\\sqrt x\\) ទ្រនាប់ (កោងចុះ) ហើយបន្ទាត់ប៉ះនៅខាងលើក្រាប"]', 3, NULL, 2, 'mcq', '\(\sqrt{15}\approx3{,}87\,298<3{,}875\) ; \(f''''<0\) (ក្រាបទ្រនាប់) ដូច្នេះបន្ទាត់ប៉ះនៅលើក្រាប។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20824, 'ចំពោះ \(y=x^2\) ត្រង់ \(x=1\), \(\Delta x=dx=0{,}01\) តើ \(\Delta y\) ធៀបនឹង \(dy\) យ៉ាងណា ?', NULL, '["\\(\\Delta y=0{,}0\\,201>dy=0{,}02\\)", "\\(\\Delta y=0{,}0\\,199<dy=0{,}02\\)", "\\(\\Delta y=0{,}0\\,201<dy=0{,}02\\)", "\\(\\Delta y=0{,}02=dy\\)"]', 0, NULL, 2, 'mcq', '\(\Delta y=1{,}01^2-1=0{,}0\,201\) ហើយ \(dy=2(1)(0{,}01)=0{,}02\) ; \(\Delta y-dy=(\Delta x)^2=0{,}0\,001\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20825, 'កាំរង្វង់ \(r=10\ \text{cm}\) វាស់លម្អៀង \(\pm0{,}1\ \text{cm}\) (កំហុសធៀប \(1\%\)) ។ តើកំហុសធៀបនៃផ្ទៃក្រឡា \(A=\pi r^2\) ប្រហែលប៉ុន្មាន ?', NULL, '["\\(1\\%\\)", "\\(4\\%\\)", "\\(0{,}5\\%\\)", "\\(2\\%\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{dA}{A}=\dfrac{2\pi r\,dr}{\pi r^2}=2\dfrac{dr}r=2\times1\%=2\%\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20826, 'ដោយអនុវត្តវិសមភាពកំណើនមានកំណត់ចំពោះ \(f(x)=\sqrt{1+x}\) លើ \(\left[0,\dfrac12\right]\) (ដែល \(\dfrac1{\sqrt6}\le f''(x)\le\dfrac12\)) ព្រំក្រោមនៃ \(\sqrt{1{,}5}\) គឺ ៖', NULL, '["\\(1\\)", "\\(1+\\dfrac14=1{,}25\\)", "\\(1+\\dfrac{1}{2\\sqrt6}\\approx1{,}204\\)", "\\(1+\\dfrac{1}{\\sqrt6}\\approx1{,}408\\)"]', 2, NULL, 3, 'mcq', '\(f(x)\ge f(0)+\dfrac{1}{\sqrt6}(x-0)\) ជាមួយ \(x=\dfrac12\) ៖ \(1+\dfrac1{2\sqrt6}\approx1{,}204\) (ពិត \(\sqrt{1{,}5}\approx1{,}2\,247\) ក្នុង \([1{,}204;\ 1{,}25]\))។', 'វិសមភាពកំណើនមានកំណត់', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20827, 'តម្លៃលក់ \(p(x)=30-0{,}1x\) ហើយប្រាក់ចំណាយ \(C(x)=0{,}05x^2+6x+200\) ។ តើប្រាក់ចំណេញអតិបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(1\\,000\\)", "\\(760\\)", "\\(560\\)", "\\(800\\)"]', 1, NULL, 3, 'mcq', '\(P(x)=(30x-0{,}1x^2)-(0{,}05x^2+6x+200)=-0{,}15x^2+24x-200\) ; \(P''=-0{,}3x+24=0\) ឱ្យ \(x=80\) ; \(P(80)=-960+1\,920-200=760\) (ត្រង់ \(R''=C''=14\))។', 'ប្រាក់ចំណេញម៉ាជីណាល', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20828, 'ប្រាក់ចំណាយ \(C(x)=0{,}5x^2+10x\) ។ តើ \(C(21)-C(20)\) ខុសពី \(C''(20)\) ប៉ុន្មាន ?', NULL, '["\\(0{,}5\\)", "\\(0\\)", "\\(1\\)", "\\(0{,}25\\)"]', 0, NULL, 3, 'mcq', '\(C(21)-C(20)=0{,}5\cdot41+10=30{,}5\) ហើយ \(C''(x)=x+10\) ដូច្នេះ \(C''(20)=30\) ; ភាពខុស \(=\dfrac12C''''=0{,}5\)។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20829, 'ការអះអាងមួយណាត្រឹមត្រូវ ពីទំនាក់ទំនងរវាង \(\overline C\) និង \(C''\) ត្រង់ចំណុចដែលប្រាក់ចំណាយមធ្យមតូចបំផុត ?', NULL, '["\\(\\overline C''(x)=0\\) ដូច្នេះ \\(C''(x)=\\overline C(x)\\) (ប្រាក់ចំណាយម៉ាជីណាលស្មើប្រាក់ចំណាយមធ្យម)", "\\(C''(x)=0\\)", "\\(C''(x)>\\overline C(x)\\) ជានិច្ច", "\\(C(x)=\\overline C(x)\\)"]', 0, NULL, 3, 'mcq', '\(\overline C=\dfrac Cx\) ; \(\overline C''=\dfrac{xC''-C}{x^2}=0\) នាំឱ្យ \(C''=\dfrac Cx=\overline C\)។', 'ប្រាក់ចំណាយមធ្យម', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20830, 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ \(\tan46^\circ\)។', NULL, '["\\(1+\\dfrac{\\pi}{180}\\approx1{,}017\\)", "\\(1+\\dfrac{\\pi}{90}\\approx1{,}035\\)", "\\(1+\\dfrac{\\pi}{45}\\approx1{,}070\\)", "\\(\\dfrac{\\sqrt2}2+\\dfrac\\pi{180}\\)"]', 1, NULL, 3, 'mcq', '\((\tan x)''=\dfrac1{\cos^2x}\) ; ត្រង់ \(x=45^\circ\) មាន \(\dfrac1{\cos^2 45^\circ}=2\) ដូច្នេះ \(dy=2\cdot\dfrac\pi{180}=\dfrac\pi{90}\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20831, 'ស៊ីឡាំងមួយមាន \(r=5\ \text{cm}\), \(h=10\ \text{cm}\) វាស់លម្អៀង \(dr=0{,}1\) និង \(dh=0{,}2\) (cm) ។ តើមាឌ \(V=\pi r^2h\) លម្អៀងប្រហែលប៉ុន្មាន ?', NULL, '["\\(25\\pi\\ \\text{cm}^3\\)", "\\(5\\pi\\ \\text{cm}^3\\)", "\\(15\\pi\\ \\text{cm}^3\\)", "\\(10\\pi\\ \\text{cm}^3\\)"]', 2, NULL, 3, 'mcq', 'ដេរីវេ \(V\) ទាក់ទង \(r\) (ឱ្យ \(h\) ថេរ) និងទាក់ទង \(h\) (ឱ្យ \(r\) ថេរ) ៖ \(dV=2\pi rh\,dr+\pi r^2\,dh=2\pi\cdot50\cdot0{,}1+25\pi\cdot0{,}2=10\pi+5\pi=15\pi\) (ដេរីវេទាក់ទងអថេរម្ដងមួយៗ រួចបូក)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'hard', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
