INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20832, 'ប៉េងប៉ោងស្វ៊ែរមួយ \(V=\dfrac43\pi r^3\) រីកពី \(r=10\ \text{cm}\) ទៅ \(10{,}3\ \text{cm}\) ដូចក្នុងរូប (បន្ទាត់ប៉ះត្រង់ \(r=10\)) ។ តើមាឌកើនប្រហែលប៉ុន្មាន ?', 'g12sc-871c4b5474.svg', '["\\(120\\pi\\approx377\\ \\text{cm}^3\\)", "\\(12\\pi\\approx38\\ \\text{cm}^3\\)", "\\(400\\pi\\approx1\\,257\\ \\text{cm}^3\\)", "\\(30\\pi\\approx94\\ \\text{cm}^3\\)"]', 0, NULL, 3, 'mcq', '\(dV=4\pi r^2\,dr=4\pi\cdot100\cdot0{,}3=120\pi\)។', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'pisa', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
