INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20833, 'ហាងនំផលិតនំបុ័ង \(x\) ដុំ ដោយប្រាក់ចំណាយ \(C(x)=0{,}02x^2+4x+300\) ដុល្លារ ដូចក្នុងរូប (បន្ទាត់ប៉ះត្រង់ \(x=100\)) ។ តើនំដុំទី \(101\) មានតម្លៃផលិតប្រហែលប៉ុន្មាន ?', 'g12sc-7d24eb3033.svg', '["\\(0{,}02\\) ដុល្លារ", "\\(8\\) ដុល្លារ", "\\(700\\) ដុល្លារ", "\\(4\\) ដុល្លារ"]', 1, NULL, 3, 'mcq', '\(C''(x)=0{,}04x+4\) ដូច្នេះ \(C''(100)=8\) ដុល្លារ (ពិត \(C(101)-C(100)=8{,}02\))។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'pisa', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
