INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20834, 'តម្លៃលក់ \(p(x)=120-0{,}4x\) ដុល្លារ ដូច្នេះប្រាក់ចំណូលសរុប \(R(x)=120x-0{,}4x^2\) ដូចក្នុងរូប ។ តើប្រាក់ចំណូលដែលបានពីការលក់ឯកតាទី \(101\) ប្រហែលប៉ុន្មាន ?', 'g12sc-8e8098ff43.svg', '["\\(0\\) ដុល្លារ", "\\(120\\) ដុល្លារ", "\\(80\\) ដុល្លារ", "\\(40\\) ដុល្លារ"]', 3, NULL, 3, 'mcq', '\(R''(x)=120-0{,}8x\) ដូច្នេះ \(R''(100)=40\) ដុល្លារ។', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'pisa', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
