INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20835, 'ប្រាក់ចំណេញ \(P(x)=-0{,}1x^2+30x-500\) ដុល្លារ ដូចក្នុងរូប ។ តើប្រាក់ចំណេញអតិបរមាស្មើប៉ុន្មាន ?', 'g12sc-b68abc6970.svg', '["\\(1\\,500\\) ដុល្លារ", "\\(150\\) ដុល្លារ", "\\(1\\,750\\) ដុល្លារ", "\\(2\\,250\\) ដុល្លារ"]', 2, NULL, 3, 'mcq', '\(P''=-0{,}2x+30=0\) ឱ្យ \(x=150\) ; \(P(150)=-2\,250+4\,500-500=1\,750\)។', 'ប្រាក់ចំណេញម៉ាជីណាល', 'pisa', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
