INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20836, 'ប្រាក់ចំណាយសរុប \(C(x)=0{,}02x^2+10x+800\) ដុល្លារ ដូច្នេះប្រាក់ចំណាយមធ្យម \(\overline C(x)\) មានក្រាបដូចក្នុងរូប ។ តើប្រាក់ចំណាយមធ្យមអប្បបរមាស្មើប៉ុន្មាន ?', 'g12sc-844156b6e9.svg', '["\\(20\\) ដុល្លារ/ដុំ", "\\(10\\) ដុល្លារ/ដុំ", "\\(800\\) ដុល្លារ/ដុំ", "\\(18\\) ដុល្លារ/ដុំ"]', 3, NULL, 3, 'mcq', '\(\overline C''=0{,}02-\dfrac{800}{x^2}=0\) ឱ្យ \(x=200\) ; \(\overline C(200)=4+10+4=18\)។', 'ប្រាក់ចំណាយមធ្យម', 'pisa', 1, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20837, 'គេមាន \(y=x^3\) ។ ក. គណនា \(dy\) ត្រង់ \(x=2\) និង \(dx=0{,}1\) ។ ខ. គណនា \(\Delta y\) ។ គ. គណនា \(dy-\Delta y\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(f''(x)=3x^2\) ដូច្នេះ \(f''(2)=12\) (1 ពិន្ទុ)
\(dy=f''(2)\,dx=12\times0{,}1=1{,}2\) (1 ពិន្ទុ)
ខ. \(\Delta y=f(2{,}1)-f(2)=(2{,}1)^3-2^3=9{,}261-8\) (1 ពិន្ទុ)
\(\Delta y=1{,}261\) (1 ពិន្ទុ)
គ. \(dy-\Delta y=1{,}2-1{,}261=-0{,}061\) (ដូច្នេះ \(dy\approx\Delta y\) កាលណា \(dx\) តូច)។ (1 ពិន្ទុ)', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'easy', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20838, 'ប្រើឌីផេរ៉ង់ស្យែលរកតម្លៃប្រហែលនៃ \(\sqrt[3]{8{,}12}\) ហើយប្រៀបធៀបនឹងតម្លៃពិត ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(f(x)=\sqrt[3]x\) ; \(x=8\) និង \(dx=0{,}12\) (1 ពិន្ទុ)
\(f''(x)=\dfrac1{3\sqrt[3]{x^2}}\) ដូច្នេះ \(f''(8)=\dfrac1{3\cdot4}=\dfrac1{12}\) (1 ពិន្ទុ)
\(dy=\dfrac1{12}\times0{,}12=0{,}01\) (1 ពិន្ទុ)
\(\sqrt[3]{8{,}12}\approx f(8)+dy=2+0{,}01=2{,}01\) (1 ពិន្ទុ)
តម្លៃពិត \(\sqrt[3]{8{,}12}\approx2{,}00\,997\) ដូច្នេះកំហុស \(<0{,}0\,001\)។ (1 ពិន្ទុ)', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'medium', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20839, 'ប្រាក់ចំណាយ \(C(x)=0{,}1x^2+5x+300\) ពាន់រៀល ។ ក. គណនា \(C(51)-C(50)\) ។ ខ. គណនាប្រាក់ចំណាយម៉ាជីណាល \(C''(50)\) ។ គ. ប្រៀបធៀបលទ្ធផលទាំងពីរ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(C(50)=250+250+300=800\) ពាន់រៀល (1 ពិន្ទុ)
\(C(51)=260{,}1+255+300=815{,}1\) ដូច្នេះ \(C(51)-C(50)=15{,}1\) (1 ពិន្ទុ)
ខ. \(C''(x)=0{,}2x+5\) ដូច្នេះ \(C''(50)=15\) (1 ពិន្ទុ)
គ. \(C''(50)=15\approx15{,}1=C(51)-C(50)\) (1 ពិន្ទុ)
ភាពខុស \(0{,}1\) តូច ដូច្នេះប្រាក់ចំណាយម៉ាជីណាលជាតម្លៃប្រហែលល្អនៃប្រាក់ចំណាយឯកតាបន្ទាប់។ (1 ពិន្ទុ)', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'medium', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20840, 'តម្លៃលក់ \(p(x)=50-0{,}2x\) ហើយប្រាក់ចំណាយ \(C(x)=0{,}1x^2+10x+100\) ។ ក. សរសេរ \(R(x)\) និង \(P(x)\) ។ ខ. គណនា \(P(41)-P(40)\) និង \(P''(40)\) ។ គ. បកស្រាយ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(R(x)=(50-0{,}2x)x=50x-0{,}2x^2\) (1 ពិន្ទុ)
\(P(x)=R-C=-0{,}3x^2+40x-100\) (1 ពិន្ទុ)
ខ. \(P(40)=-480+1\,600-100=1\,020\) ; \(P(41)=-504{,}3+1\,640-100=1\,035{,}7\) ដូច្នេះ \(P(41)-P(40)=15{,}7\) (1 ពិន្ទុ)
\(P''(x)=-0{,}6x+40\) ដូច្នេះ \(P''(40)=16\) (1 ពិន្ទុ)
គ. \(P''(40)=16\approx15{,}7\) ជាប្រាក់ចំណេញប្រហែលពីឯកតាទី \(41\) (\(P''>0\) ដូច្នេះលក់បន្ថែមនៅតែចំណេញបន្ថែម)។ (1 ពិន្ទុ)', 'ប្រាក់ចំណេញម៉ាជីណាល', 'medium', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20841, 'ក. បង្ហាញថា ចំពោះគ្រប់ \(x,y\in\mathbb{R}\) គេបាន \(|\sin x-\sin y|\le|x-y|\) ។ ខ. ទាញរកព្រំលើនៃ \(|\sin0{,}31-\sin0{,}3|\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាង \(f(t)=\sin t\) ដូច្នេះ \(f''(t)=\cos t\) (1 ពិន្ទុ)
ចំពោះគ្រប់ \(t\) មាន \(|f''(t)|=|\cos t|\le1\) ដូច្នេះ \(M=1\) (1 ពិន្ទុ)
តាមទ្រឹស្ដីបទ \(|f(b)-f(a)|\le M|b-a|\) បាន \(|\sin x-\sin y|\le|x-y|\) (1 ពិន្ទុ)
ខ. ជំនួស \(x=0{,}31\) និង \(y=0{,}3\) ៖ \(|\sin0{,}31-\sin0{,}3|\le|0{,}31-0{,}3|=0{,}01\) (1 ពិន្ទុ)
ពិតប្រាកដ \(\sin0{,}31-\sin0{,}3\approx0{,}0\,095<0{,}01\) ស្របគ្នា។ (1 ពិន្ទុ)', 'វិសមភាពកំណើនមានកំណត់', 'medium', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20842, 'ក. ដោយប្រើវិសមភាពកំណើនមានកំណត់ បង្ហាញថាចំពោះ \(0\le a<b<\dfrac\pi2\) គេបាន \(\dfrac{b-a}{\cos^2a}\le\tan b-\tan a\le\dfrac{b-a}{\cos^2b}\) ។ ខ. ទាញរកព្រំនៃ \(\tan\left(\dfrac\pi4+0{,}05\right)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(f(x)=\tan x\) មាន \(f''(x)=\dfrac1{\cos^2x}\) កើនលើ \(\left[0,\dfrac\pi2\right)\) (ព្រោះ \(\cos x\) ចុះ) (1 ពិន្ទុ)
លើ \([a,b]\) គេបាន \(m=f''(a)=\dfrac1{\cos^2a}\le f''(x)\le f''(b)=\dfrac1{\cos^2b}=M\) (1 ពិន្ទុ)
វិសមភាពកំណើនមានកំណត់ ៖ \(m(b-a)\le f(b)-f(a)\le M(b-a)\) គឺវិសមភាពដែលត្រូវបង្ហាញ (1 ពិន្ទុ)
ខ. យក \(a=\dfrac\pi4\), \(b=\dfrac\pi4+0{,}05\) ៖ \(\cos^2a=\dfrac12\) ដូច្នេះ ព្រំក្រោម \(0{,}05\times2=0{,}1\) (1 ពិន្ទុ)
ព្រំលើ \(\dfrac{0{,}05}{\cos^2b}\approx0{,}1\,111\) ដូច្នេះ \(1{,}1\le\tan\left(\dfrac\pi4+0{,}05\right)\le1{,}1\,111\) (ពិត \(\approx1{,}1\,054\))។ (1 ពិន្ទុ)', 'វិសមភាពកំណើនមានកំណត់', 'hard', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20843, 'ប្រាក់ចំណាយ \(C(x)=0{,}02x^2+10x+800\) ដុល្លារ ។ ក. សរសេរ \(\overline C(x)\) ។ ខ. រកកម្រិតផលិតកម្មដែល \(\overline C\) តូចបំផុត និងតម្លៃអប្បបរមា ។ គ. បង្ហាញថាត្រង់ចំណុចនោះ \(C''(x)=\overline C(x)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\overline C(x)=\dfrac{C(x)}x=0{,}02x+10+\dfrac{800}x\) ($x>0$) (1 ពិន្ទុ)
ខ. \(\overline C''(x)=0{,}02-\dfrac{800}{x^2}\) ; \(\overline C''=0\) ឱ្យ \(x^2=40\,000\) គឺ \(x=200\) (1 ពិន្ទុ)
សញ្ញា \(\overline C''\) ប្ដូរពី \(-\) ទៅ \(+\) ដូច្នេះអប្បបរមា ; \(\overline C(200)=4+10+4=18\) ដុល្លារ (1 ពិន្ទុ)
គ. \(C''(x)=0{,}04x+10\) ដូច្នេះ \(C''(200)=18\) (1 ពិន្ទុ)
ដូច្នេះ \(C''(200)=18=\overline C(200)\) ស្របតាមទំនាក់ទំនង \(\overline C''=\dfrac{xC''-C}{x^2}=0\)។ (1 ពិន្ទុ)', 'ប្រាក់ចំណាយមធ្យម', 'hard', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20844, 'វាយតម្លៃសេចក្ដីអះអាង "ការប៉ាន់ស្មានតាមឌីផេរ៉ង់ស្យែលតែងតែតូចជាងតម្លៃពិត" ដោយធ្វើតេស្តជាមួយ \(\sqrt{15}\) និង \((1{,}01)^2\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក្រឡាតេស្ត ១ ៖ \(\sqrt{15}\approx\sqrt{16}+\dfrac{-1}{2\cdot4}=3{,}875\) ខណៈ \(\sqrt{15}\approx3{,}87\,298\) (1 ពិន្ទុ)
ការប៉ាន់ស្មាន \(3{,}875>3{,}87\,298\) ធំជាងតម្លៃពិត (ក្រាប \(\sqrt x\) ទ្រនាប់ \(f''''<0\)) (1 ពិន្ទុ)
តេស្ត ២ ៖ \((1{,}01)^2\approx1+2(0{,}01)=1{,}02\) ខណៈពិត \(1{,}0\,201\) (1 ពិន្ទុ)
ការប៉ាន់ស្មាន \(1{,}02<1{,}0\,201\) តូចជាងតម្លៃពិត (ក្រាប \(x^2\) កោងឡើង \(f''''>0\)) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ សេចក្ដីអះអាងមិនត្រឹមត្រូវ ; ទិសនៃកំហុសអាស្រ័យនឹងទ្រនាប់ (\(f''''<0\Rightarrow\) ប៉ាន់ស្មានធំជាង ; \(f''''>0\Rightarrow\) ប៉ាន់ស្មានតូចជាង)។ (1 ពិន្ទុ)', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'hard', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20845, 'ហាងមួយមានតម្លៃលក់ \(p(x)=30-0{,}1x\) និងប្រាក់ចំណាយ \(C(x)=0{,}05x^2+6x+200\) ។ ក. សរសេរ \(R(x)\) និង \(P(x)\) ។ ខ. រកកម្រិតលក់ដែលចំណេញអតិបរមា និងចំណេញនោះ ។ គ. បង្ហាញថាត្រង់ចំណុចនោះ \(R''(x)=C''(x)\) ហើយពន្យល់ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(R(x)=(30-0{,}1x)x=30x-0{,}1x^2\) ; \(P(x)=R-C=-0{,}15x^2+24x-200\) (1 ពិន្ទុ)
ខ. \(P''(x)=-0{,}3x+24=0\) ឱ្យ \(x=80\) ; \(P''''=-0{,}3<0\) ដូច្នេះអតិបរមា (1 ពិន្ទុ)
\(P(80)=-960+1\,920-200=760\) (1 ពិន្ទុ)
គ. \(R''(x)=30-0{,}2x\) ដូច្នេះ \(R''(80)=14\) ; \(C''(x)=0{,}1x+6\) ដូច្នេះ \(C''(80)=14\) (1 ពិន្ទុ)
ពន្យល់ ៖ \(P''=R''-C''=0\) ដូច្នេះចំណេញអតិបរមាកាលណាចំណូលម៉ាជីណាលស្មើចំណាយម៉ាជីណាល (លក់ឯកតាបន្ថែមមិនបន្ថែមចំណេញទៀត)។ (1 ពិន្ទុ)', 'ប្រាក់ចំណេញម៉ាជីណាល', 'hard', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20846, 'ទំហំបាល់ស្វ៊ែរមួយវាស់បានអង្កត់ផ្ចិត \(20\ \text{cm}\) លម្អៀង \(\pm0{,}2\ \text{cm}\) ។ មាឌ \(V=\dfrac43\pi r^3\) ដូចក្នុងរូប ។ ក. រកកាំនិងលម្អៀង \(dr\) ។ ខ. គណនាលម្អៀងនៃមាឌ \(dV\) ។ គ. គណនាកំហុសធៀបនៃមាឌ ហើយប្រៀបធៀបនឹងកំហុសធៀបនៃកាំ ។', 'g12sc-871c4b5474.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(r=\dfrac{20}2=10\ \text{cm}\) ហើយ \(dr=\pm0{,}1\ \text{cm}\) (1 ពិន្ទុ)
ខ. \(V''(r)=4\pi r^2\) ដូច្នេះ \(dV=4\pi r^2\,dr=4\pi(100)(\pm0{,}1)=\pm40\pi\approx\pm126\ \text{cm}^3\) (1 ពិន្ទុ)
មាឌ \(V=\dfrac43\pi\cdot1\,000\approx4\,189\ \text{cm}^3\) (1 ពិន្ទុ)
គ. កំហុសធៀបមាឌ \(\dfrac{dV}{V}=\dfrac{40\pi}{\frac43\pi\cdot1\,000}=0{,}03=3\%\) (1 ពិន្ទុ)
កំហុសធៀបកាំ \(\dfrac{dr}{r}=1\%\) ដូច្នេះកំហុសមាឌប្រហែល \(3\) ដងកំហុសកាំ (\(\dfrac{dV}{V}=3\dfrac{dr}r\))។ (1 ពិន្ទុ)', 'ឌីផេរ៉ង់ស្យែលនិងតម្លៃប្រហែល', 'pisa', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20847, 'ហាងនំផលិតនំបុ័ង \(x\) ដុំ ដោយប្រាក់ចំណាយ \(C(x)=0{,}02x^2+4x+300\) ដុល្លារ ដូចក្នុងរូប ។ ក. រកប្រាក់ចំណាយម៉ាជីណាល \(C''(x)\) ។ ខ. ប៉ាន់ស្មានតម្លៃផលិតនំដុំទី \(101\) ។ គ. គណនាតម្លៃពិត \(C(101)-C(100)\) ហើយប្រៀបធៀប ។', 'g12sc-7d24eb3033.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(C''(x)=0{,}04x+4\) (1 ពិន្ទុ)
ខ. \(C''(100)=0{,}04\cdot100+4=8\) ដុល្លារ (1 ពិន្ទុ)
គ. \(C(101)=0{,}02\cdot10\,201+404+300=908{,}02\) (1 ពិន្ទុ)
\(C(100)=200+400+300=900\) ដូច្នេះ \(C(101)-C(100)=8{,}02\) ដុល្លារ (1 ពិន្ទុ)
ការប៉ាន់ស្មាន \(8\) និងតម្លៃពិត \(8{,}02\) ខុសគ្នាត្រឹម \(0{,}02\) ដុល្លារ ដូច្នេះចំណាយម៉ាជីណាលទុកចិត្តបាន។ (1 ពិន្ទុ)', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'pisa', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20848, 'តម្លៃលក់ \(p(x)=120-0{,}4x\) ដុល្លារ ដែល \(x\) ជាបរិមាណលក់ ។ ក. សរសេរ \(R(x)\) ។ ខ. រកប្រាក់ចំណូលម៉ាជីណាល \(R''(x)\) ហើយប៉ាន់ស្មានចំណូលពីឯកតាទី \(101\) ។ គ. រកបរិមាណលក់ដែលចំណូលអតិបរមា និងតម្លៃលក់នោះ ។', 'g12sc-8e8098ff43.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(R(x)=p(x)\cdot x=120x-0{,}4x^2\) (1 ពិន្ទុ)
ខ. \(R''(x)=120-0{,}8x\) ; \(R''(100)=40\) ដុល្លារ (ចំណូលពីឯកតាទី \(101\)) (1 ពិន្ទុ)
គ. \(R''(x)=0\) ឱ្យ \(x=150\) ; \(R''''=-0{,}8<0\) អតិបរមា (1 ពិន្ទុ)
\(R(150)=18\,000-9\,000=9\,000\) ដុល្លារ (1 ពិន្ទុ)
តម្លៃលក់ \(p(150)=120-60=60\) ដុល្លារ/ឯកតា ; ត្រង់ \(x=150\) ប្រាក់ចំណូលម៉ាជីណាលស្មើសូន្យ។ (1 ពិន្ទុ)', 'ប្រាក់ចំណាយនិងប្រាក់ចំណូលម៉ាជីណាល', 'pisa', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
