INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20849, 'ហាងមួយលក់ក្នុងតម្លៃ \(p(x)=40-0{,}2x\) ដុល្លារ ហើយប្រាក់ចំណាយ \(C(x)=0{,}1x^2+10x+200\) ដុល្លារ ។ ក. សរសេរ \(P(x)\) ដូចក្នុងរូប ។ ខ. រកកម្រិតលក់ដែលចំណេញអតិបរមា ។ គ. ពិនិត្យ \(P''(50)\) និង \(P(51)-P(50)\) ហើយបកស្រាយ ។', 'g12sc-57d1c21adf.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(R(x)=40x-0{,}2x^2\) ; \(P(x)=R-C=-0{,}3x^2+30x-200\) (1 ពិន្ទុ)
