INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20850, 'ប្រាក់ចំណាយ \(C(x)=0{,}5x^2+20x+1\,250\) ដុល្លារ ។ ក. សរសេរ \(\overline C(x)\) ដូចក្នុងរូប ។ ខ. រក \(x\) ដែល \(\overline C\) តូចបំផុត ។ គ. វាយតម្លៃសេចក្ដីអះអាង "ផលិតកាន់តែច្រើនតែងបន្ថយប្រាក់ចំណាយមធ្យម" ។', 'g12sc-b52812d42f.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\overline C(x)=\dfrac{C(x)}x=0{,}5x+20+\dfrac{1\,250}x\) (1 ពិន្ទុ)
ខ. \(\overline C''(x)=0{,}5-\dfrac{1\,250}{x^2}=0\) ឱ្យ \(x^2=2\,500\) គឺ \(x=50\) (1 ពិន្ទុ)
\(\overline C(50)=25+20+25=70\) ដុល្លារ (អប្បបរមា ព្រោះ \(\overline C''\) ប្ដូរ \(-\to+\)) (1 ពិន្ទុ)
គ. ពិនិត្យ \(x=100\) ៖ \(\overline C(100)=50+20+12{,}5=82{,}5>70\) (1 ពិន្ទុ)
ដូច្នេះសេចក្ដីអះអាងមិនត្រឹមត្រូវ ៖ ថយចុះតែកាលណា \(x<50\) ហើយកើនវិញកាលណា \(x>50\) (ចំណាយថេរចែកបានច្រើន តែ \(0{,}5x\) កើន)។ (1 ពិន្ទុ)', 'ប្រាក់ចំណាយមធ្យម', 'pisa', 0, '12SC', 'អនុវត្តន៍ផ្សេងទៀតនៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
